#!/usr/bin/env python3
"""Regenerate the bundled synthetic PCAP from deterministic Ethernet frame fixtures."""
from pathlib import Path
import struct

FRAMES_HEX = [
    "0200000000530200000000100800450000430001400040113c69c000020acb007135cf080035002fe3f212340100000100000000000008747261696e696e67076578616d706c6504746573740000010001",
    "0200000000100200000000530800450000530002400040113c58cb007135c000020a0035cf08003fdc6512348180000100010000000008747261696e696e67076578616d706c6504746573740000010001c00c000100010000012c0004c6336414",
    "0200000000200200000000100800450000280003400040064e7bc000020ac6336414c93a0050000003e8000000005002faf0fb2c0000",
    "0200000000100200000000200800450000280004400040064e7ac6336414c000020a0050c93a00001b58000003e95012faf0dfc30000",
    "0200000000200200000000100800450000280005400040064e79c000020ac6336414c93a0050000003e900001b595010faf0dfc40000",
    "",
    "",
    "0200000000300200000000100800450000280008400040064e6cc000020ac633641ec93b01bb00000bb8000000005002faf0f1e60000",
    "0200000000100200000000300800450000280009400040064e6bc633641ec000020a01bbc93b0000232800000bb95012faf0cead0000",
    "020000000030020000000010080045000028000a400040064e6ac000020ac633641ec93b01bb00000bb9000023295010faf0ceae0000",
    "02000000003002000000001008004500003d000b400040064e54c000020ac633641ec93b01bb00000bb9000023295018faf0a48e0000170303001000000000000000000000000000000000",
]
TIMES_US = [
    0,
    29999,
    99999,
    119999,
    130000,
    160000,
    200000,
    400000,
    420000,
    430000,
    460000,
]

def build_capture(path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("wb") as f:
        f.write(struct.pack("<IHHIIII", 0xa1b2c3d4, 2, 4, 0, 0, 65535, 1))
        for delta_us, frame_hex in zip(TIMES_US, FRAMES_HEX):
            sec, usec = divmod(1_700_000_000_000_000 + delta_us, 1_000_000)
            frame = bytes.fromhex(frame_hex)
            f.write(struct.pack("<IIII", sec, usec, len(frame), len(frame)))
            f.write(frame)

if __name__ == "__main__":
    output = Path(__file__).resolve().parents[1] / "captures" / "sample_traffic.pcap"
    build_capture(output)
    print(f"Wrote synthetic training capture: {output}")
